:root {
  /* Colors */
  --color-paper-canvas: #f7f7f4;
  --color-linen-panel: #f2f1ed;
  --color-stone-tile: #ebeae5;
  --color-pebble-fill: #e6e5e0;
  --color-quartz-knob: #e1e0db;
  --color-ink: #26251e;
  --color-graphite-caption: #0000008c;
  --color-ash-hint: #00000061;
  --color-smoke-hairline: #26251e1a;
  --color-ember-link: #f54e00;
  --color-amber-plan: #c08532;
  --color-forest-merge: #34785c;
  --color-moss-diff: #1f8a65;

  /* Typography — Font Families */
  --font-cursor-gothic: "CursorGothic", "Geist", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-berkeley-mono: "berkeleyMono", "JetBrains Mono", "Commit Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-system-ui: system-ui, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.27;
  --tracking-small: 0.05px;
  --text-caption: 12px;
  --leading-caption: 1.625;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.55;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.5;
  --tracking-body: 0.14px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0.08px;
  --text-heading: 22px;
  --leading-heading: 1.3;
  --tracking-heading: -0.11px;
  --text-display: 26px;
  --leading-display: 1.25;
  --tracking-display: -0.325px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-20: 20px;
  --spacing-22: 22px;
  --spacing-30: 30px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-67: 67px;
  --spacing-90: 90px;

  /* Layout */
  --layout-page-max-width: 1300px;
  --layout-section-gap: 90px;
  --layout-card-padding: 22px;
  --layout-element-gap: 8px;
  --layout-nav-height: 52px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;
  --radius-xl: 10px;
  --radius-2xl: 12px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 4px;
  --radius-pills: 9999px;
  --radius-buttons: 9999px;
  --radius-inputs: 8px;
  --radius-tags: 4px;
  --radius-badges: 9999px;
  --radius-avatars: 9999px;
  --radius-images: 4px;
  --radius-inner-tiles: 10px;
  --radius-small-cards: 12px;
  --radius-small-elements: 2px;

  /* Shadows */
  --shadow-subtle: 0px 0px 0px 2px #fcfcfc;
  --shadow-sm: 0px 10px 15px -3px #0000001a, 0px 4px 6px -4px #0000001a;
  --shadow-md: 0px 0px 0px 1px #26251e1a, 0px 18px 36px -18px #00000047;
  --shadow-lg: 0px 28px 70px 0px #00000024, 0px 14px 32px 0px #0000001a, 0px 0px 0px 1px #26251e1a;
  --shadow-lg-2: 0px 25px 50px -12px #00000040, 0px 12px 24px -8px #00000026, 0px 0px 0px 0.5px #26251e1a;
  --shadow-xl: 0px 22px 70px 4px #0000004d, 0px 0px 0px 0.5px #00000026;

  /* Surfaces */
  --surface-paper-canvas: #f7f7f4;
  --surface-linen-panel: #f2f1ed;
  --surface-stone-tile: #ebeae5;
  --surface-pebble-fill: #e6e5e0;
  --surface-ink: #26251e;
}

